from pathlib import Path
# Add PageResponse.java
p = Path('apps/mindmark-server/src/main/java/com/mindmark/server/common/api/PageResponse.java')
p.write_text('''package com.mindmark.server.common.api;\n\nimport java.util.List;\n\npublic record PageResponse<T>(\n    List<T> items,\n    long total,\n    int page,\n    int pageSize,\n    int totalPages,\n    boolean hasPrevious,\n    boolean hasNext\n) {\n\n    private static final int DEFAULT_PAGE_SIZE = 10;\n    private static final int MAX_PAGE_SIZE = 100;\n\n    public static <T> PageResponse<T> fromList(List<T> source, Integer requestedPage, Integer requestedPageSize) {\n        int safePageSize = normalizePageSize(requestedPageSize);\n        int totalPages = Math.max(1, (int) Math.ceil((double) source.size() / safePageSize));\n        int safePage = Math.min(Math.max(requestedPage == null ? 1 : requestedPage, 1), totalPages);\n        int fromIndex = Math.min((safePage - 1) * safePageSize, source.size());\n        int toIndex = Math.min(fromIndex + safePageSize, source.size());\n\n        return new PageResponse<>(\n            source.subList(fromIndex, toIndex),\n            source.size(),\n            safePage,\n            safePageSize,\n            totalPages,\n            safePage > 1,\n            safePage < totalPages\n        );\n    }\n\n    public static int normalizePageSize(Integer requestedPageSize) {\n        if (requestedPageSize == null || requestedPageSize <= 0) {\n            return DEFAULT_PAGE_SIZE;\n        }\n        return Math.min(requestedPageSize, MAX_PAGE_SIZE);\n    }\n}\n''', encoding='utf-8')
